('lib/content/gpx_scolarite/dps_dpg/cadres_juridiques_pages/flagrant_delit/flagrant_delit_notion_page.dart','f00039','B. La flagrance par présomption',39,'_Paragraph','la clameur publique et la découverte d’objets, de traces ou d’indices laissant penser à sa participation au crime ou au délit.','la clameur publique et la découverte d’objets, de traces ou d’indices laissant penser à sa participation au crime ou au délit.','{}'::jsonb,true),
