('lib/content/gpx_scolarite/dps_dpg/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00004','Informations générales',4,'_Paragraph','L’enquête de flagrant délit se caractérise par l’urgence et par des pouvoirs ','L’enquête de flagrant délit se caractérise par l’urgence et par des pouvoirs ','{"font_weight_hints":["FontWeight.w900"],"font_size_hints":["21"]}'::jsonb,true),
